/** The same bounds are enforced before upload and by the private upload verifier. */
export const ORIGINAL_AUDIO_MAX_BYTES = 50 * 1024 * 1024;
export const ORIGINAL_AUDIO_MAX_SECONDS = 600;
export const ORIGINAL_AUDIO_ACCEPT = '.wav,.mp3,.m4a,audio/wav,audio/mpeg,audio/mp4';
export type OriginalAudioInfo = { mime: 'audio/wav' | 'audio/mpeg' | 'audio/mp4'; extension: 'wav' | 'mp3' | 'm4a'; durationSec: number };

function fail(): never { throw new Error('Choose a complete WAV, MP3 or M4A audio file between 1 second and 10 minutes, under 50 MB.'); }
/** Container inspection does not execute a decoder. All lengths and loop counts are bounded. */
export function inspectOriginalAudio(bytes: Uint8Array): OriginalAudioInfo {
  if (bytes.length < 44 || bytes.length > ORIGINAL_AUDIO_MAX_BYTES) return fail();
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const text = (offset: number, length: number) => String.fromCharCode(...bytes.subarray(offset, offset + length));
  const finish = (durationSec: number, mime: OriginalAudioInfo['mime'], extension: OriginalAudioInfo['extension']) => {
    if (!Number.isFinite(durationSec) || durationSec < 1 || durationSec > ORIGINAL_AUDIO_MAX_SECONDS) return fail();
    return { durationSec, mime, extension };
  };
  if (text(0, 4) === 'RIFF' && text(8, 4) === 'WAVE') {
    if (view.getUint32(4, true) + 8 !== bytes.length) return fail();
    let rate = 0, block = 0, dataBytes = 0, format = false;
    for (let offset = 12, chunks = 0; offset + 8 <= bytes.length && chunks++ < 10000;) {
      const name = text(offset, 4), size = view.getUint32(offset + 4, true), start = offset + 8;
      if (size > bytes.length - start) return fail();
      if (name === 'fmt ') {
        if (size < 16 || format) return fail();
        const codec = view.getUint16(start, true), channels = view.getUint16(start + 2, true);
        const samples = view.getUint32(start + 4, true), bits = view.getUint16(start + 14, true);
        rate = view.getUint32(start + 8, true); block = view.getUint16(start + 12, true);
        if (![1, 3].includes(codec) || channels < 1 || channels > 8 || samples < 8000 || samples > 192000
          || ![8, 16, 24, 32, 64].includes(bits) || block !== channels * bits / 8 || rate !== samples * block) return fail();
        format = true;
      } else if (name === 'data') dataBytes += size;
      offset = start + size + (size % 2);
    }
    if (!format || !dataBytes || dataBytes % block) return fail();
    return finish(dataBytes / rate, 'audio/wav', 'wav');
  }
  if (text(4, 4) === 'ftyp') {
    type Box = { name: string; start: number; end: number };
    let boxCount = 0;
    const boxes = (start: number, end: number): Box[] => {
      const result: Box[] = [];
      for (let offset = start; offset < end;) {
        if (offset + 8 > end || ++boxCount > 100000) return fail();
        let size = view.getUint32(offset), header = 8;
        if (size === 1) {
          if (offset + 16 > end) return fail();
          const large = view.getBigUint64(offset + 8); if (large > BigInt(ORIGINAL_AUDIO_MAX_BYTES)) return fail();
          size = Number(large); header = 16;
        } else if (size === 0) size = end - offset;
        if (size < header || offset + size > end) return fail();
        result.push({ name: text(offset + 4, 4), start: offset + header, end: offset + size }); offset += size;
      }
      return result;
    };
    const child = (box: Box, name: string) => boxes(box.start, box.end).find(item => item.name === name);
    const top = boxes(0, bytes.length), moov = top.find(box => box.name === 'moov');
    if (!moov || !top.some(box => box.name === 'mdat' && box.end > box.start)) return fail();
    let duration = 0, tracks = 0;
    for (const trak of boxes(moov.start, moov.end).filter(box => box.name === 'trak')) {
      const mdia = child(trak, 'mdia'); if (!mdia) return fail();
      const hdlr = child(mdia, 'hdlr'), mdhd = child(mdia, 'mdhd'), minf = child(mdia, 'minf');
      if (!hdlr || hdlr.end - hdlr.start < 12 || text(hdlr.start + 8, 4) !== 'soun' || !mdhd || !minf) return fail();
      const version = bytes[mdhd.start], timescaleOffset = mdhd.start + (version === 1 ? 20 : 12);
      if (![0, 1].includes(version) || timescaleOffset + 4 > mdhd.end) return fail();
      const timescale = view.getUint32(timescaleOffset); if (!timescale) return fail();
      const stbl = child(minf, 'stbl'), dinf = child(minf, 'dinf');
      const stts = stbl && child(stbl, 'stts'), dref = dinf && child(dinf, 'dref');
      if (!stts || stts.start + 8 > stts.end || !dref || dref.start + 8 > dref.end) return fail();
      // External data references could otherwise describe media outside these bytes.
      const refs = boxes(dref.start + 8, dref.end);
      if (!refs.length || refs.some(ref => ref.name !== 'url ' || ref.end - ref.start !== 4 || (view.getUint32(ref.start) & 1) !== 1)) return fail();
      const entries = view.getUint32(stts.start + 4); if (entries > 100000 || stts.start + 8 + entries * 8 !== stts.end) return fail();
      let ticks = 0;
      for (let i = 0; i < entries; i++) {
        const p = stts.start + 8 + i * 8; ticks += view.getUint32(p) * view.getUint32(p + 4);
        if (!Number.isSafeInteger(ticks) || ticks / timescale > ORIGINAL_AUDIO_MAX_SECONDS) return fail();
      }
      duration = Math.max(duration, ticks / timescale); tracks++;
    }
    if (tracks !== 1) return fail();
    return finish(duration, 'audio/mp4', 'm4a');
  }
  let offset = 0;
  if (text(0, 3) === 'ID3') {
    if ([bytes[6], bytes[7], bytes[8], bytes[9]].some(value => value > 127)) return fail();
    offset = 10 + (bytes[6] << 21 | bytes[7] << 14 | bytes[8] << 7 | bytes[9]);
    if (bytes[5] & 16) offset += 10;
  }
  let duration = 0, frames = 0;
  while (offset + 4 <= bytes.length) {
    if (bytes.length - offset === 128 && text(offset, 3) === 'TAG') { offset = bytes.length; break; }
    const header = view.getUint32(offset), version = (header >>> 19) & 3, layer = (header >>> 17) & 3;
    const rateIndex = (header >>> 10) & 3, bitrateIndex = (header >>> 12) & 15, padding = (header >>> 9) & 1;
    if ((header >>> 21) !== 0x7ff || version === 1 || layer !== 1 || rateIndex === 3 || !bitrateIndex || bitrateIndex === 15) return fail();
    const rate = [44100, 48000, 32000][rateIndex] / (version === 3 ? 1 : version === 2 ? 2 : 4);
    const bitrate = (version === 3 ? [0,32,40,48,56,64,80,96,112,128,160,192,224,256,320] : [0,8,16,24,32,40,48,56,64,80,96,112,128,144,160])[bitrateIndex] * 1000;
    const size = Math.floor((version === 3 ? 144 : 72) * bitrate / rate) + padding;
    if (size < 4 || offset + size > bytes.length) return fail();
    offset += size; duration += (version === 3 ? 1152 : 576) / rate; frames++;
    if (duration > ORIGINAL_AUDIO_MAX_SECONDS || frames > 100000) return fail();
  }
  if (!frames || offset !== bytes.length) return fail();
  return finish(duration, 'audio/mpeg', 'mp3');
}

import { inspectOriginalAudio, ORIGINAL_AUDIO_MAX_BYTES } from '../../../shared/originalAudio.ts';
type Upload = { id: string; ownerId: string; path: string; mime: string; bytes: number; sha256: string; status: string; soundId?: string; objectVersion?: string | null };
type Dependencies = {
  getUpload(request: Request, id: string, signal: AbortSignal): Promise<Upload | null>;
  object(upload: Upload, signal: AbortSignal): Promise<{ version: string } | null>;
  download(upload: Upload, signal: AbortSignal): Promise<Response>;
  finish(upload: Upload, duration: number, sha256: string, version: string, signal: AbortSignal): Promise<string | null>;
  digest(bytes: Uint8Array): Promise<string>;
};
const headers = { 'Content-Type': 'application/json', 'Cache-Control': 'private, no-store',
  'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, apikey, content-type, x-client-info',
  'Access-Control-Allow-Methods': 'POST, OPTIONS' };
const uuid = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
export function createMusicFinalizeHandler(deps: Dependencies) {
  const reply = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers });
  return async (request: Request): Promise<Response> => {
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers });
    if (request.method !== 'POST') return reply(405, { error: 'Method not allowed' });
    const controller = new AbortController(), timer = setTimeout(() => controller.abort(), 45000);
    let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
    let bodyReader: ReadableStreamDefaultReader<Uint8Array> | undefined;
    // Stream implementations may ignore cancellation or never resolve it.
    // Cleanup must not extend the verification deadline or retain a lock.
    const closeReader = (value?: ReadableStreamDefaultReader<Uint8Array>) => {
      if (!value) return;
      void value.cancel().catch(() => {});
      try { value.releaseLock(); } catch { /* A completed/released reader needs no cleanup. */ }
    };
    const abortReaders = () => { closeReader(bodyReader); closeReader(reader); };
    const requestAborted = () => controller.abort();
    controller.signal.addEventListener('abort', abortReaders, { once: true });
    if (request.signal.aborted) controller.abort();
    else request.signal.addEventListener('abort', requestAborted, { once: true });
    const bounded=<T>(task:Promise<T>):Promise<T>=>new Promise((resolve,reject)=>{
      const expired=()=>reject(new Error('AUDIO_VERIFICATION_DEADLINE'));
      if(controller.signal.aborted){void task.catch(()=>{});expired();return;}
      controller.signal.addEventListener('abort',expired,{once:true});
      task.then(value=>{controller.signal.removeEventListener('abort',expired);resolve(value);},error=>{controller.signal.removeEventListener('abort',expired);reject(error);});
    });
    try {
      if (!request.headers.get('Authorization')?.startsWith('Bearer ')) return reply(401, { error: 'Sign in again to finish the upload.' });
      bodyReader = request.body?.getReader(); if (!bodyReader) return reply(400, { error: 'Upload ID required.' });
      let text = '', bodyBytes = 0;
      try {
        const decoder = new TextDecoder();
        while (true) { const chunk = await bounded(bodyReader.read()); if (chunk.done) break; bodyBytes += chunk.value.byteLength;
          if (bodyBytes > 1024) return reply(413, { error: 'Request too large.' }); text += decoder.decode(chunk.value, { stream: true }); }
      } finally { closeReader(bodyReader); bodyReader = undefined; }
      if (controller.signal.aborted) return reply(408, { error: 'The upload check timed out. Retry the same upload.' });
      let id: string;
      try { id = JSON.parse(text).requestId; } catch { return reply(400, { error: 'Upload ID required.' }); }
      if (typeof id !== 'string' || !uuid.test(id)) return reply(400, { error: 'Upload ID required.' });
      const upload = await bounded(deps.getUpload(request, id, controller.signal));
      if (!upload || upload.id !== id || !uuid.test(upload.ownerId) || !new RegExp(`^${upload.ownerId}/${id}\\.(wav|mp3|m4a)$`, 'i').test(upload.path))
        return reply(403, { error: 'This upload is unavailable for this account.' });
      if (upload.status === 'ready' && upload.soundId) return reply(200, { soundId: upload.soundId });
      if (upload.status !== 'reserved' || upload.bytes < 44 || upload.bytes > ORIGINAL_AUDIO_MAX_BYTES) return reply(400, { error: 'Upload is outside the supported limits.' });
      const object = await bounded(deps.object(upload, controller.signal)); if (!object) return reply(409, { error: 'Finish uploading the audio, then retry verification.' });
      const response = await bounded(deps.download(upload, controller.signal));
      if (!response.ok || !response.body || Number(response.headers.get('Content-Length') || upload.bytes) !== upload.bytes) {
        void response.body?.cancel().catch(() => {}); return reply(409, { error: 'The uploaded file is incomplete. Retry the upload.' });
      }
      reader = response.body.getReader(); const bytes = new Uint8Array(upload.bytes); let offset = 0;
      while (true) { const chunk = await bounded(reader.read()); if (chunk.done) break;
        if (offset + chunk.value.byteLength > bytes.length) return reply(413, { error: 'The uploaded audio exceeds its reservation.' });
        bytes.set(chunk.value, offset); offset += chunk.value.byteLength;
      }
      if (offset !== bytes.length) return reply(409, { error: 'The uploaded file is incomplete. Retry the upload.' });
      const info = inspectOriginalAudio(bytes), digest = await bounded(deps.digest(bytes));
      if (digest !== upload.sha256 || info.mime !== upload.mime) return reply(422, { error: 'The audio bytes do not match the reserved file. Choose the original file again.' });
      if (controller.signal.aborted) return reply(408, { error: 'The upload check timed out. Retry the same upload.' });
      const current = await bounded(deps.getUpload(request, id, controller.signal));
      if (!current || current.ownerId !== upload.ownerId) return reply(403, { error: 'The account changed. Return to the account that uploaded this audio.' });
      const soundId = await bounded(deps.finish(upload, info.durationSec, digest, object.version, controller.signal));
      if (!soundId) return reply(409, { error: 'The audio changed while it was checked. Retry verification.' });
      return reply(200, { soundId, durationSec: info.durationSec });
    } catch (error) {
      if (controller.signal.aborted) return reply(408, { error: 'The upload check timed out. Retry the same upload.' });
      if (error instanceof Error && error.message.startsWith('Choose a complete')) return reply(422, { error: error.message });
      return reply(503, { error: 'Audio verification is temporarily unavailable. Your upload is kept for retry.' });
    } finally {
      clearTimeout(timer);
      controller.signal.removeEventListener('abort', abortReaders);
      request.signal.removeEventListener('abort', requestAborted);
      closeReader(bodyReader); closeReader(reader);
    }
  };
}

import { createClient } from 'npm:@supabase/supabase-js@2.112.3';
import { createMusicFinalizeHandler } from './handler.ts';
const base = Deno.env.get('SUPABASE_URL')!, key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const service = createClient(base, key, { auth: { persistSession: false, autoRefreshToken: false } });
const caller = (request: Request, signal: AbortSignal) => createClient(base, Deno.env.get('SUPABASE_ANON_KEY')!, {
  global: { headers: { Authorization: request.headers.get('Authorization') || '' }, fetch: (input, init) => fetch(input, { ...init, signal }) },
  auth: { persistSession: false, autoRefreshToken: false },
});
Deno.serve(createMusicFinalizeHandler({
  async getUpload(request, id, signal) {
    const client = caller(request, signal), { data: identity, error: authError } = await client.auth.getUser();
    if (authError || !identity.user || identity.user.is_anonymous) return null;
    const { data, error } = await client.rpc('get_original_audio_upload', { p_request_id: id }).abortSignal(signal);
    return error || data?.ownerId !== identity.user.id ? null : data;
  },
  async object(upload) { return upload.objectVersion ? { version: upload.objectVersion } : null; },
  download: (upload, signal) => fetch(`${base}/storage/v1/object/authenticated/music-audio/${upload.path}`, {
    headers: { Authorization: `Bearer ${key}`, apikey: key, 'Cache-Control': 'no-store' }, signal,
  }),
  async finish(upload, duration, sha256, version, signal) {
    const { data, error } = await service.rpc('finish_original_audio_upload', {
      p_request_id: upload.id, p_owner: upload.ownerId, p_duration: duration, p_sha256: sha256, p_object_version: version,
    }).abortSignal(signal);
    return error ? null : data;
  },
  async digest(bytes) { return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))).map(byte => byte.toString(16).padStart(2, '0')).join(''); },
}));
